WITH with_latest AS (SELECT s.id, s.product_name, s.brand, s.stock_qty, s.launch_date, s.tags, s.supplier_id, top1.units, top1.revenue FROM products s LEFT JOIN LATERAL (SELECT c.units, c.revenue FROM store_sales c WHERE c.product_id = s.id ORDER BY c.units DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT supplier_id, COUNT(*) FILTER (WHERE brand = 'Acme') AS acme_rows, COUNT(*) FILTER (WHERE brand = 'Globex') AS globex_rows, COUNT(*) FILTER (WHERE brand = 'Initech') AS initech_rows FROM with_latest GROUP BY 1
